        out['dry_run_rows']=con.execute("SELECT id,plan,migration,status,error,created_at FROM migration_dry_run_log ORDER BY id").fetchall()
    if 'customer_segment_rollup' in tables:
        out['rollup_sample']=con.execute("SELECT COUNT(*) FROM customer_segment_rollup").fetchone()
    con.close(); return out
